SELECT jsonb_build_object(
         'generated_at', to_char(now() AT TIME ZONE 'Asia/Taipei', 'YYYY-MM-DD"T"HH24:MI:SS') || '+08:00',
         'missing', coalesce(jsonb_agg(jsonb_build_object('type', type, 'name', name, 'needed_by', needed_by) ORDER BY type, name) FILTER (WHERE NOT ok), '[]'::jsonb),
         'present_count', count(*) FILTER (WHERE ok),
         'total_checked', count(*)
       ) AS result
FROM items;
